/// A unit of distance. KILOMETRE: kilometres. MILE: international miles. UNKNOWN: a unit this version does not name; a symbol this version does not know is read as UNKNOWN.
enum AxtExampleCarDistanceUnit {
  kilometre('KILOMETRE'),
  mile('MILE'),
  unknown('UNKNOWN');

  const AxtExampleCarDistanceUnit(this.symbol);

  /// The Avro symbol of the value.
  final String symbol;

  /// The value of the Avro symbol [symbol]. Throws [ArgumentError] for any other string.
  static AxtExampleCarDistanceUnit fromSymbol(String symbol) =>
      switch (symbol) {
        'KILOMETRE' => kilometre,
        'MILE' => mile,
        'UNKNOWN' => unknown,
        _ => throw ArgumentError.value(
          symbol,
          'symbol',
          'not a symbol of AxtExampleCarDistanceUnit',
        ),
      };
}

