/// How the text of a note is written. PLAIN: plain text, lines separated by LF. MARKDOWN: CommonMark. A symbol this version does not know is read as PLAIN.
enum AxtExampleNoteFormat {
  plain('PLAIN'),
  markdown('MARKDOWN');

  const AxtExampleNoteFormat(this.symbol);

  /// The Avro symbol of the value.
  final String symbol;

  /// The value of the Avro symbol [symbol]. Throws [ArgumentError] for any other string.
  static AxtExampleNoteFormat fromSymbol(String symbol) => switch (symbol) {
    'PLAIN' => plain,
    'MARKDOWN' => markdown,
    _ => throw ArgumentError.value(
      symbol,
      'symbol',
      'not a symbol of AxtExampleNoteFormat',
    ),
  };
}

